	/// <summary>Compute the union of cotangential contours.</summary>
	/// <param name="contours">Input XLD contours.</param>
	/// <param name="unionContours">Output XLD contours.</param>
	/// <param name="fitClippingLength">Length of the part of a contour to skip for the determination of tangents. Default: 0.0</param>
	/// <param name="fitLength">Length of the part of a contour to use for the determination of tangents. Default: 30.0</param>
	/// <param name="maxTangAngle">Maximum angle difference between two contours' tangents. Default: 0.78539816</param>
	/// <param name="maxDist">Maximum distance of the contours' end points. Default: 25.0</param>
	/// <param name="maxDistPerp">Maximum distance of the contours' end points perpendicular to their tangents. Default: 10.0</param>
	/// <param name="maxOverlap">Maximum overlap of two contours. Default: 2.0</param>
	/// <param name="mode">Mode describing the treatment of the contours' attributes. Default: "attr_forget"</param>
	/// <remarks>
	///   <para><b>功能说明</b></para>
	///   <para>合并切线方向接近的轮廓</para>
	///   <para><b>典型场景</b></para>
	///   <para>轮廓（XLD）生成、合并与几何拟合</para>
	///   <para><b>调用示例</b></para>
	///   <code>
	///   JlObject contours = ...;
	///   JlOperatorSet.UnionCotangentialContoursXld(contours, out JlObject unionContours, 0.0, 30.0, 0.78539816, 25.0, 10.0, 2.0, "attr_forget");
	///   </code>
	///   <para><b>相关算子</b></para>
	///   <para>UnionCollinearContoursXld、UnionAdjacentContoursXld、SelectContoursXld</para>
	/// </remarks>
	public static void UnionCotangentialContoursXld(JlObject contours, out JlObject unionContours, JlTuple fitClippingLength, JlTuple fitLength, JlTuple maxTangAngle, JlTuple maxDist, JlTuple maxDistPerp, JlTuple maxOverlap, JlTuple mode)
	{
		IntPtr proc = JlNativeApi.PreCall(0);
		JlNativeApi.Store(proc, 1, contours);
		JlNativeApi.Store(proc, 0, fitClippingLength);
		JlNativeApi.Store(proc, 1, fitLength);
		JlNativeApi.Store(proc, 2, maxTangAngle);
		JlNativeApi.Store(proc, 3, maxDist);
		JlNativeApi.Store(proc, 4, maxDistPerp);
		JlNativeApi.Store(proc, 5, maxOverlap);
		JlNativeApi.Store(proc, 6, mode);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(fitClippingLength);
		JlNativeApi.UnpinTuple(fitLength);
		JlNativeApi.UnpinTuple(maxTangAngle);
		JlNativeApi.UnpinTuple(maxDist);
		JlNativeApi.UnpinTuple(maxDistPerp);
		JlNativeApi.UnpinTuple(maxOverlap);
		JlNativeApi.UnpinTuple(mode);
		err = JlObject.LoadNew(proc, 1, err, out unionContours);
		JlNativeApi.PostCall(proc, err);
		GC.KeepAlive(contours);
	}



	/// <summary>Create control data of a NURBS curve that interpolates given points.</summary>
	/// <param name="rows">Row coordinates of input point list.</param>
	/// <param name="cols">Column coordinates of input point list.</param>
	/// <param name="tangents">Tangents at first and last point. Default: []</param>
	/// <param name="degree">Order of the output curve. Default: 3</param>
	/// <param name="ctrlRows">Row coordinates of the control polygon.</param>
	/// <param name="ctrlCols">Column coordinates of the control polygon.</param>
	/// <param name="knots">The knot vector of the output curve.</param>
	/// <remarks>
	///   <para><b>功能说明</b></para>
	///   <para>根据给定点生成 NURBS 插值曲线的控制数据</para>
	///   <para><b>典型场景</b></para>
	///   <para>轮廓（XLD）生成、合并与几何拟合</para>
	///   <para><b>调用示例</b></para>
	///   <code>
	///   JlTuple rows = ...;
	///   JlTuple cols = ...;
	///   JlOperatorSet.GenNurbsInterp(rows, cols, new JlTuple(), 3, out JlTuple ctrlRows, out JlTuple ctrlCols, out JlTuple knots);
	///   </code>
	/// </remarks>
	public static void GenNurbsInterp(JlTuple rows, JlTuple cols, JlTuple tangents, JlTuple degree, out JlTuple ctrlRows, out JlTuple ctrlCols, out JlTuple knots)
	{
		IntPtr proc = JlNativeApi.PreCall(3);
		JlNativeApi.Store(proc, 0, rows);
		JlNativeApi.Store(proc, 1, cols);
		JlNativeApi.Store(proc, 2, tangents);
		JlNativeApi.Store(proc, 3, degree);
		JlNativeApi.InitOCT(proc, 0);
		JlNativeApi.InitOCT(proc, 1);
		JlNativeApi.InitOCT(proc, 2);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(rows);
		JlNativeApi.UnpinTuple(cols);
		JlNativeApi.UnpinTuple(tangents);
		JlNativeApi.UnpinTuple(degree);
		err = JlTuple.LoadNew(proc, 0, JlTupleType.DOUBLE, err, out ctrlRows);
		err = JlTuple.LoadNew(proc, 1, JlTupleType.DOUBLE, err, out ctrlCols);
		err = JlTuple.LoadNew(proc, 2, JlTupleType.DOUBLE, err, out knots);
		JlNativeApi.PostCall(proc, err);
	}

	/// <summary>Transform a NURBS curve into an XLD contour.</summary>
	/// <param name="contour">The contour that approximates the NURBS curve.</param>
	/// <param name="rows">Row coordinates of the control polygon.</param>
	/// <param name="cols">Column coordinates of the control polygon.</param>
	/// <param name="knots">The knot vector u@f$u$. Default: "auto"</param>
	/// <param name="weights">The weight vector w@f$w$. Default: "auto"</param>
	/// <param name="degree">The degree p@f$p$ of the NURBS curve. Default: 3</param>
	/// <param name="maxError">Maximum distance between the NURBS curve and its approximation. Default: 1.0</param>
	/// <param name="maxDistance">Maximum distance between two subsequent Contour points. Default: 5.0</param>
	/// <remarks>
	///   <para><b>功能说明</b></para>
	///   <para>Transform NURBS 曲线 为 XLD 轮廓。</para>
	///   <para><b>典型场景</b></para>
	///   <para>轮廓（XLD）生成、合并与几何拟合</para>
	///   <para><b>调用示例</b></para>
	///   <code>
	///   JlTuple rows = ...;
	///   JlTuple cols = ...;
	///   JlOperatorSet.GenContourNurbsXld(out JlObject contour, rows, cols, "auto", "auto", 3, 1.0, 5.0);
	///   </code>
	/// </remarks>
	public static void GenContourNurbsXld(out JlObject contour, JlTuple rows, JlTuple cols, JlTuple knots, JlTuple weights, JlTuple degree, JlTuple maxError, JlTuple maxDistance)
	{
		IntPtr proc = JlNativeApi.PreCall(4);
		JlNativeApi.Store(proc, 0, rows);
		JlNativeApi.Store(proc, 1, cols);
		JlNativeApi.Store(proc, 2, knots);
		JlNativeApi.Store(proc, 3, weights);
		JlNativeApi.Store(proc, 4, degree);
		JlNativeApi.Store(proc, 5, maxError);
		JlNativeApi.Store(proc, 6, maxDistance);
		JlNativeApi.InitOCT(proc, 1);
		int err = JlNativeApi.CallProcedure(proc);
		JlNativeApi.UnpinTuple(rows);
		JlNativeApi.UnpinTuple(cols);
		JlNativeApi.UnpinTuple(knots);
		JlNativeApi.UnpinTuple(weights);
		JlNativeApi.UnpinTuple(degree);
		JlNativeApi.UnpinTuple(maxError);
		JlNativeApi.UnpinTuple(maxDistance);
		err = JlObject.LoadNew(proc, 1, err, out contour);
		JlNativeApi.PostCall(proc, err);
	}

